    acoesTeletrabalho: function(cfg, metodo, titulo_acao) {
        var selected = this.getSelectionModel().getSelected();
        if (selected) {

            const wnd = Ext._create('Ext.Window', {
                title: 'Tem certeza que deseja '+titulo_acao+' plano selecionado ?',
                width: 500,
                height: 250,
                modal: true,
                border: false,
                items: [
                    Ext._create('Ext.form.FormPanel', {
                        border: false,
                        frame: true,
                        items: [
                            {
                                allowBlank: false,
                                fieldLabel: 'Observação',
                                name: 'observacao',
                                xtype: 'textarea',
                                width: 360,
                                height:120
                            },
                            {
                                fieldLabel: 'Anexo',
                                xtype: 'ged-fileuploadfield',
                                name: 'anexo_id',
                                allowBlank: false,
                            }
                        ]
                    })
                ],
                buttons: [
                    {
                        text: 'Confirmar',
                        scope: this,
                        handler: function () {
                            var observacao = wnd.getComponent(0).getForm().findField('observacao').getValue();
                            var anexo_id = wnd.getComponent(0).getForm().findField('anexo_id').getValue(); 
                            var params = {
                                'plano_id': selected.id,
                                'observacao':observacao,
                                'anexo_id':anexo_id
                            }
                            this._realizarReq(params, 'RHGestorTeletrabalho', metodo);
                            wnd.destroy();
                        }
                    },
                    {
                        text: 'Fechar',
                        handler: function () { wnd.destroy(); }
                    }
                ]
            }).show();

        } else Ext.Msg.show({
            msg: 'Selecione um plano.',
            icon: Ext.Msg.ERROR,
            buttons: Ext.Msg.OK
        })
    },


    _realizarReq: function(params, nome_classe, nome_metodo){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(nome_classe,nome_metodo),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                var icon = obj.success == true ? Ext.Msg.INFO : Ext.Msg.ERROR;
                Ext.Msg.show({
                    width:"400px",
                    title: this.title,
                    icon: icon,
                    buttons: Ext.Msg.OK,
                    msg: obj.message
                });
                if(obj.success == true){ this.getStore().reload(); }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-core icon-core-csv',
                tooltip: 'Download Metas Teletrabalho',
                scope: this,
                label: 'Download',
                handler: function(action, index) {
                    var dados = action._store.getAt(index).data
                    params = { 
                        'pk': dados.pk,
                    };
                    this.doDownloadServidor(params)
                }
            },
        ];
    },

    doDownloadServidor: function(params) {
        var config = {
            mov_teletrabalho_pk: params.pk,
            start: 0,
            limit: this.getStore().getTotalCount(),
            format: 'text/csv'
        };
        
        var rest = this.factoryRestful();
        var url = rest.getRoute('export').url + '?' + Ext.urlEncode(config);

        window.open(url, '_self');
    },

