    __setFilterPropertyDefault: function (gridAutoLoad) {
        var filterSituationMenuValue = [];
        var filterStatusMenuValue = [];
        var filterSaldoDevedorMenuValue = [];

        this.situationMenuValue.forEach(
            function (item) {

                if (item.checked) {
                    filterSituationMenuValue.push(item.value);
                }
            }
        );

        this.statusMenuValue.forEach(
            function (item) {

                if (item.checked) {
                    filterStatusMenuValue.push(item.value);
                }
            }
        );

        this.saldoDevedorMenuValue.forEach(
            function (item) {

                if (item.checked) {
                    filterSaldoDevedorMenuValue.push(item.value);
                }
            }
        );

        if (filterSituationMenuValue.length > 0) {
            this.setFilterProperty('ativo__in', filterSituationMenuValue, 1001, false);
        }

        if (filterStatusMenuValue.length > 0) {
            this.setFilterProperty('situacao__in', filterStatusMenuValue, 1002, false);
        }

        if (filterSaldoDevedorMenuValue.length > 0) {
            this.setFilterProperty('possui_saldo_devedor__in', filterSaldoDevedorMenuValue, 1003, false);
        }

        if (gridAutoLoad) {
            var store = this.getStore();
            store.load({});
        }
    },

